b'def parse_size(size_str):
    size_str = size_str.strip()
    value, unit = size_str.split()
    value = float(value)
    if unit == 'B':
        return int(value)
    elif unit == 'KB':
        return int(value * 1024)
    elif unit == 'MB':
        return int(value * 1024 * 1024)
    else:
        raise ValueError("Invalid unit")'
